// === PREPARER SORTIE TELEGRAM ===
try {
  const item = ($input.first() && $input.first().json) || {};
  const output = String(item.output || '').trim();
  const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

  // 1) chatId depuis Telegram Trigger (toujours fiable)
  let chatId = '';
  try {
    const trig = $('Telegram Trigger').first();
    if (trig && trig.json && trig.json.message && trig.json.message.chat) {
      chatId = String(trig.json.message.chat.id);
    }
  } catch (e) { chatId = ''; }

  // 2) Chercher URL DALL-E dans les appels d'outils
  const dalleRe = /https:\/\/oaidalleapiprodscus\.blob\.core\.windows\.net\/[^\s"'\)\]]+/;
  let imageUrl = '';
  for (let i = 0; i < steps.length; i++) {
    const step = steps[i];
    if (!step || !step.observation) continue;
    const obs = step.observation;
    const obsStr = typeof obs === 'string' ? obs : JSON.stringify(obs);
    const m = obsStr.match(dalleRe);
    if (m) { imageUrl = m[0]; break; }
  }

  // 3) Fallback: chercher URL dans le texte de l'agent
  if (!imageUrl && output) {
    const m1 = output.match(dalleRe);
    if (m1) imageUrl = m1[0];
    else {
      const imgRe = /https?:\/\/[^\s<>"'\)\]]+\.(?:png|jpg|jpeg|gif|webp)(?:[?#][^\s<>"'\)\]]*)?/i;
      const m2 = output.match(imgRe);
      if (m2) imageUrl = m2[0];
    }
  }

  // 4) Légende
  let caption = output;
  if (imageUrl) {
    caption = output.split(imageUrl).join('').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  }
  if (!caption) caption = '\uD83C\uDFA8';
  if (caption.length > 1024) caption = caption.substring(0, 1021) + '...';

  // 5) Texte (jamais vide, max 4096)
  let text = output;
  if (!text) text = 'D\u00e9sol\u00e9, aucune r\u00e9ponse g\u00e9n\u00e9r\u00e9e.';
  if (text.length > 4096) text = text.substring(0, 4093) + '...';

  return [{ json: { chatId: chatId, imageUrl: imageUrl, text: text, caption: caption } }];

} catch (err) {
  // Garde-fou: toujours retourner quelque chose de valide
  let fallbackChatId = '';
  try { fallbackChatId = String($('Telegram Trigger').first().json.message.chat.id); } catch(e2) {}
  return [{ json: {
    chatId: fallbackChatId,
    imageUrl: '',
    text: 'Erreur dans Preparer Sortie: ' + (err && err.message ? err.message : String(err)),
    caption: ''
  } }];
}
